val worstStallMs = AtomicLong()
thread(isDaemon = true, name = "stall-meter") {
    while (true) {
        val t0 = System.nanoTime()
        Thread.sleep(1)
        val lateMs = (System.nanoTime() - t0) / 1_000_000 - 1
        worstStallMs.accumulateAndGet(lateMs, ::maxOf)   // publish and reset it once a minute
    }
}

