class Careful(val marginMs: Long) : HolderPolicy {
    // count from the send: the service started the lease later, so this is never late
    override fun believedExpiry(sentAt: Long, handledAt: Long, ttlMs: Long) = sentAt + ttlMs

    override fun mayStartWork(now: Long, believedExpiry: Long) = believedExpiry - now >= marginMs

    // check again after the work, right before sending
    override fun maySendWrite(now: Long, believedExpiry: Long) = believedExpiry - now >= marginMs
}
// A pause that starts after maySendWrite returns true and outlasts what is left of the lease:
// no code of the holder runs during it, so nothing in the holder can stop the write it already decided to send.
